  private void PaintTableCell(object sender,DataGridViewCellPaintingEventArgs e){if(e.RowIndex<0 || (e.ColumnIndex!=3&&e.ColumnIndex!=4&&e.ColumnIndex!=5))return;if(e.ColumnIndex==4){e.PaintBackground(e.ClipBounds,true);var textBounds=new Rectangle(e.CellBounds.X+9,e.CellBounds.Y+8,e.CellBounds.Width-18,27);TextRenderer.DrawText(e.Graphics,Convert.ToString(e.FormattedValue),e.CellStyle.Font,textBounds,Theme.Muted,TextFormatFlags.SingleLine|TextFormatFlags.EndEllipsis);var ratio=grid.Rows[e.RowIndex].Cells[4].Tag;double used=ratio is double?(double)ratio:-1;if(used>=0){var track=new Rectangle(e.CellBounds.X+10,e.CellBounds.Bottom-12,e.CellBounds.Width-20,3);using(var bg=new SolidBrush(Color.FromArgb(230,235,243)))e.Graphics.FillRectangle(bg,track);track.Width=(int)(track.Width*Math.Max(0,Math.Min(1,used)));using(var fill=new SolidBrush(used>.9?Color.FromArgb(218,142,69):Theme.Blue))e.Graphics.FillRectangle(fill,track);}e.Handled=true;return;}e.PaintBackground(e.ClipBounds,true);string text=Convert.ToString(e.FormattedValue);Color ink=e.ColumnIndex==5?(server?Color.FromArgb(173,65,78):Theme.Blue):text.Contains("Đã kết nối")||text.Contains("Đang chia sẻ")?Color.FromArgb(23,132,93):Color.FromArgb(151,119,51);var rect=new Rectangle(e.CellBounds.X+8,e.CellBounds.Y+10,Math.Max(10,e.CellBounds.Width-16),e.CellBounds.Height-20);using(var shape=MacButton.Round(rect,6))using(var brush=new SolidBrush(e.ColumnIndex==5?Color.White:Color.FromArgb(242,247,251)))e.Graphics.FillPath(brush,shape);TextRenderer.DrawText(e.Graphics,text,e.CellStyle.Font,rect,ink,TextFormatFlags.HorizontalCenter|TextFormatFlags.VerticalCenter|TextFormatFlags.SingleLine|TextFormatFlags.EndEllipsis);e.Handled=true;}
  private static Button FindButton(Control parent,string text){foreach(Control c in parent.Controls){if(c is Button&&c.Text==text)return (Button)c;var found=FindButton(c,text);if(found!=null)return found;}return null;}
  private Label Summary(TableLayoutPanel parent,int col,string title,string value,string icon) {var card=new Card{Dock=DockStyle.Fill,Margin=new Padding(0,0,col<2?14:0,0),Padding=new Padding(14)};var picture=new PictureBox{Image=SuiteGlyph.Image(icon,64,Theme.Blue),Location=new Point(16,25),Size=new Size(28,28),SizeMode=PictureBoxSizeMode.Zoom};card.Controls.Add(picture);var caption=Label(title,8);caption.ForeColor=Theme.Muted;caption.Location=new Point(58,14);card.Controls.Add(caption);var label=Label(value,13,true);label.AutoSize=false;label.AutoEllipsis=true;label.Font=new Font("Segoe UI",10,FontStyle.Bold);label.Location=new Point(58,35);label.Height=40;card.Controls.Add(label);card.SizeChanged+=(a,b)=>{label.Width=Math.Max(30,card.Width-74);caption.MaximumSize=new Size(Math.Max(30,card.Width-74),22);};parent.Controls.Add(card,col,0);return label;}
