  private FlowLayoutPanel Actions(FlowLayoutPanel body){var row=new FlowLayoutPanel{Height=42,WrapContents=false,Margin=new Padding(0,12,0,0)};body.Controls.Add(row);return row;}
  private void BuildServerCards(){
   leftCard.Height=420;rightCard.Height=420;var body=CardBody(leftCard,"Cấu hình ổ chia sẻ","Chọn một ổ trong danh sách hoặc tạo chia sẻ mới.");Field(body,"Tên chia sẻ",share);Field(body,"Ổ / thư mục trên máy chủ",folder);readOnly.Text="Chỉ cho phép đọc";readOnly.Height=30;body.Controls.Add(readOnly);
   var row=Actions(body);Action(row,"Chọn thư mục",()=>{using(var picker=new FolderBrowserDialog())if(picker.ShowDialog(this)==DialogResult.OK)folder.Text=picker.SelectedPath;return Task.FromResult(0);});Action(row,"Bật chia sẻ NAS",CreateShare,true);
   var manage=Actions(body);Action(manage,"Bỏ lưu NAS",RemoveShare);Action(manage,"Sao chép địa chỉ",()=>{if(selectedShare=="")throw new Exception("Chọn NAS đã lưu trước.");Clipboard.SetText(@"\\"+Environment.MachineName+@"\"+selectedShare);message.Text="Đã sao chép địa chỉ NAS.";return Task.FromResult(0);});
   var access=CardBody(rightCard,"Tài khoản truy cập","Dùng tài khoản này trên CYAN NAS CLIENT.");Field(access,"Tài khoản Windows / NAS",user);password.UseSystemPasswordChar=true;Field(access,"Mật khẩu NAS",password);createUser.Text="Tạo tài khoản NAS riêng";createUser.Height=30;access.Controls.Add(createUser);
   var pw=Actions(access);Action(pw,"Hiện / Ẩn",()=>{if(password.UseSystemPasswordChar&&password.Text=="")password.Text=nas.LoadPassword(user.Text.Trim());password.UseSystemPasswordChar=!password.UseSystemPasswordChar;return Task.FromResult(0);});Action(pw,"Lưu mật khẩu",()=>{nas.SavePassword(user.Text.Trim(),password.Text);password.Clear();message.Text="Đã lưu mật khẩu mã hóa. Mật khẩu Windows chưa đổi.";return Task.FromResult(0);},true);
   var check=Actions(access);Action(check,"Kiểm tra mật khẩu",async()=>{await Task.Run(()=>NasService.CheckLocalPassword(user.Text.Trim(),Secret()));message.Text="Windows chấp nhận mật khẩu này.";});Action(check,"Đặt lại mật khẩu",async()=>{if(MessageBox.Show(this,"Đổi mật khẩu Windows của tài khoản NAS riêng do tool tạo?","Đặt lại mật khẩu",MessageBoxButtons.YesNo)!=DialogResult.Yes)return;await nas.Admin("SetNasPassword",Profile(),password.Text);password.Clear();});user.TextChanged+=(a,b)=>{password.Clear();password.UseSystemPasswordChar=true;};NewShare();
  }
  private string Secret(){return password.Text==""?nas.LoadPassword(user.Text.Trim()):password.Text;}
  private NasProfile Profile(){return new NasProfile{Folder=folder.Text.Trim(),Share=share.Text.Trim(),User=user.Text.Trim(),ReadOnly=readOnly.Checked,CreateUser=createUser.Checked};}
  private void NewShare(){creatingShare=true;grid.ClearSelection();selectedShare="";share.Text="CYANNAS";folder.Clear();user.Text="nasuser";password.Clear();createUser.Checked=true;share.Enabled=folder.Enabled=readOnly.Enabled=user.Enabled=createUser.Enabled=true;if(enable!=null){enable.Enabled=true;enable.Text="Bật chia sẻ NAS";}message.Text="Chia sẻ mới · Chọn thư mục và tài khoản NAS.";}
  private async Task CreateShare(){var p=Profile();if(NasService.ReadShareState(p.Share).State!="Stopped")throw new Exception("Tên NAS đã tồn tại hoặc chưa kiểm tra được. Chọn tên mới.");await nas.Admin("Create",p,password.Text);nas.RememberShare(p);if(password.Text!="")nas.SavePassword(p.User,password.Text);password.Clear();selectedShare=p.Share;creatingShare=false;await RefreshData();message.Text="Đã bật NAS · Máy khác có thể truy cập qua Tailscale.";}
  private async Task RemoveShare(){var p=Selected() as NasProfile;if(p==null)throw new Exception("Chọn NAS trong danh sách.");if(NasService.ReadShareState(p.Share).State!="Stopped")throw new Exception("Dừng NAS trước khi bỏ cấu hình. File không bị xóa.");if(MessageBox.Show(this,"Bỏ cấu hình "+p.Share+"? File và tài khoản vẫn được giữ.","Bỏ lưu NAS",MessageBoxButtons.YesNo)!=DialogResult.Yes)return;nas.ForgetShare(p.Share);NewShare();await RefreshData();}
  private async Task StopShare(){var p=Selected() as NasProfile;if(p==null)throw new Exception("Chọn NAS trong danh sách.");await nas.Admin("Remove",p);await RefreshData();}
  private object Selected(){return grid.SelectedRows.Count==0?null:grid.SelectedRows[0].Tag;}
  private void SelectRow(){if(rebindingRows)return;if(grid.SelectedRows.Count==0)return;var selected=grid.SelectedRows[0].Tag;if(server){var p=selected as NasProfile;if(p==null)return;creatingShare=false;capacity.Text=CapacityInfo.Local(p.Folder);if(selectedShare!=p.Share){share.Text=p.Share;folder.Text=p.Folder;user.Text=p.User;readOnly.Checked=p.ReadOnly;createUser.Checked=false;}selectedShare=p.Share;var active=states.ContainsKey(p.Share)&&states[p.Share].State=="Enabled";share.Enabled=folder.Enabled=readOnly.Enabled=user.Enabled=createUser.Enabled=!active;if(enable!=null){enable.Enabled=!active;enable.Text=active?"Đã bật chia sẻ":"Bật chia sẻ NAS";}if(stop!=null)stop.Enabled=active;}else{var p=selected as StorageConnection;if(p!=null){var r=engine.Runtime(p);capacity.Text=r.Capacity;if(connectionInfo!=null)connectionInfo.Text=p.Name+" · "+p.Letter+":\n\n"+StorageProviders.Find(p.Provider).Name+"\nThư mục gốc: "+p.Path+"\nTrạng thái: "+r.State+"\nDung lượng: "+r.Capacity+"\nTự kết nối: "+(p.AutoConnect?"Bật":"Tắt");message.Text=p.Name+" · "+StorageProviders.Find(p.Provider).Name+" · "+r.State+(r.Message==""?"":" · "+r.Message);}}}
  private void BuildClientCards(){var body=CardBody(leftCard,"Kết nối đang chọn","Chọn dòng trong danh sách để chỉnh sửa hoặc mở ổ.");connectionInfo=Label("NAS · máy chủ · cloud\n\nMỗi nguồn có đăng nhập, cache và ký tự ổ riêng.\n\nFTP · FTPS · SFTP · WebDAV · S3 · B2\nDropbox · OneDrive · Google Drive\nAzure Blob · Azure Files · Google Cloud Storage",10);connectionInfo.Height=172;body.Controls.Add(connectionInfo);var row=Actions(body);Action(row,"Chỉnh sửa",EditSelected);Action(row,"Kết nối lại",Reconnect,true);var manage=Actions(body);Action(manage,"Tạm ngắt",PauseSelected);Action(manage,"Bỏ lưu",RemoveSelected);
   var auto=CardBody(rightCard,"Kết nối tự động","Thông tin đăng nhập được mã hóa theo tài khoản Windows.");var startup=new CheckBox{Text="Khởi chạy Client cùng Windows",AutoSize=true,Height=38,Checked=SuiteStartup.Enabled(false)};startup.CheckedChanged+=(a,b)=>{if(!preview)SuiteStartup.Set(false,startup.Checked);};auto.Controls.Add(startup);var reconnect=new CheckBox{Text="Phục hồi sau đổi Wi-Fi / máy thức dậy",Checked=true,Enabled=false,AutoSize=true,Height=38};auto.Controls.Add(reconnect);var note=Label("Chỉ tự kết nối các cấu hình đã kiểm tra và được bật.\n\nỔ Tạm ngắt giữ nguyên trạng thái qua lần khởi động sau.\n\nĐổi mạng không cưỡng chế dừng VFS hay bỏ dữ liệu chờ upload.",9);note.ForeColor=Theme.Muted;note.Height=150;auto.Controls.Add(note);
  }
  private async Task AddConnection(){using(var dialog=new StorageDialog(engine))if(dialog.ShowDialog(this)==DialogResult.OK){await RefreshData();}}
  private async Task EditSelected(){var p=Selected() as StorageConnection;if(p==null)throw new Exception("Chọn kết nối cần sửa.");var r=engine.Runtime(p);if((r.Job!=null&&!r.Job.IsCompleted)||(r.Service!=null&&r.Service.Running)||r.Native)throw new Exception("Tạm ngắt ổ trước khi chỉnh sửa cấu hình.");using(var dialog=new StorageDialog(engine,p))if(dialog.ShowDialog(this)==DialogResult.OK)await RefreshData();}
  private async Task Reconnect(){var p=Selected() as StorageConnection;if(p==null)throw new Exception("Chọn kết nối.");p.AutoConnect=true;engine.Store.Put(p);await engine.Connect(p);await RefreshData();}
  private async Task PauseSelected(){var p=Selected() as StorageConnection;if(p==null)throw new Exception("Chọn kết nối.");await engine.Stop(p);await RefreshData();}
  private async Task RemoveSelected(){var p=Selected() as StorageConnection;if(p==null)throw new Exception("Chọn kết nối.");if(MessageBox.Show(this,"Bỏ cấu hình "+p.Name+"? File và cache được giữ lại.","Bỏ lưu",MessageBoxButtons.YesNo)!=DialogResult.Yes)return;await engine.Stop(p);var values=engine.Store.Load();values.RemoveAll(x=>x.Id==p.Id);engine.Store.Save(values);await RefreshData();}
  private Task OpenSelected(){var p=Selected() as StorageConnection;if(p==null)throw new Exception("Chọn kết nối.");if(engine.Runtime(p).State!="Đã kết nối")throw new Exception("Ổ chưa sẵn sàng. Bấm Kết nối lại để kiểm tra.");Process.Start("explorer.exe",Core.Quote(p.Letter+@":\"));return Task.FromResult(0);}
  private async Task RefreshData(){if(preview)return;if(DateTime.UtcNow>=nextNetwork){nextNetwork=DateTime.UtcNow.AddMinutes(1);try{var net=await nas.Status();network.Text=net.Ready?"Tailscale · "+net.Address:net.State=="NotInstalled"?"Chưa cài Tailscale":"Chưa đăng nhập";}catch{network.Text="Chưa sẵn sàng";}}string key=Selected() is NasProfile?((NasProfile)Selected()).Share:Selected() is StorageConnection?((StorageConnection)Selected()).Id:null;
   if(server){var shares=nas.LocalShares();var checks=await Task.Run(()=>shares.ToDictionary(p=>p.Share,p=>NasService.ReadShareState(p.Share)));rebindingRows=true;states.Clear();foreach(var pair in checks)states[pair.Key]=pair.Value;grid.Rows.Clear();foreach(var p in shares){var state=checks[p.Share];var index=grid.Rows.Add(p.Share,p.ReadOnly?"Chỉ đọc":"Đọc & ghi",p.Folder,state.Message,CapacityInfo.Local(p.Folder),state.State=="Enabled"?"Dừng NAS":"Đã dừng");grid.Rows[index].Tag=p;grid.Rows[index].Cells[4].Tag=CapacityInfo.LocalRatio(p.Folder);if(p.Share==key)grid.Rows[index].Selected=true;}if(creatingShare)grid.ClearSelection();rebindingRows=false;count.Text=checks.Values.Count(x=>x.State=="Enabled")+" / "+shares.Count+" ổ";}
   else{rebindingRows=true;var values=engine.Store.Load();grid.Rows.Clear();foreach(var p in values){var r=engine.Runtime(p);var index=grid.Rows.Add(p.Letter+":  "+p.Name,StorageProviders.Find(p.Provider).Name,p.Get("host")!=""?p.Get("host"):p.Path,!p.Verified?"Chưa xác thực":p.AutoConnect||r.Native||(r.Service!=null&&r.Service.Running)?r.State:"Tạm ngắt",r.Capacity,!p.Verified?"Thiết lập":r.State=="Đã kết nối"?"Mở ổ":"Kết nối");grid.Rows[index].Tag=p;grid.Rows[index].Cells[4].Tag=r.TotalBytes.HasValue&&r.TotalBytes.Value>0&&r.UsedBytes.HasValue?(double)r.UsedBytes.Value/r.TotalBytes.Value:-1;if(p.Id==key)grid.Rows[index].Selected=true;}rebindingRows=false;count.Text=values.Count+" kết nối";}if(!server||!creatingShare)SelectRow();}
  private async Task Work(Func<Task> action){if(busy||preview)return;busy=true;try{await action();}catch(Exception e){message.Text=e.Message;MessageBox.Show(this,e.Message,Text,MessageBoxButtons.OK,MessageBoxIcon.Warning);}finally{busy=false;}}
  private async Task NetworkSettings(){
   var net=await nas.Status();network.Text=net.Ready?"Tailscale · "+net.Address:"Chưa sẵn sàng";
   using(var dialog=new Form{Text="Mạng Tailscale",Size=new Size(600,380),StartPosition=FormStartPosition.CenterParent,Font=Font,Icon=Icon}){
    var body=new FlowLayoutPanel{Dock=DockStyle.Fill,FlowDirection=FlowDirection.TopDown,Padding=new Padding(24),WrapContents=false};dialog.Controls.Add(body);var status=Label(net.Ready?"Đã kết nối · "+net.Address:(nas.Installed?"Chưa đăng nhập Tailscale":"Chưa cài Tailscale"),12,true);status.Height=48;status.AutoSize=false;status.Width=520;body.Controls.Add(status);
    var explanation=Label("Dùng cùng mạng Tailscale trên Server và Client để truy cập NAS qua Internet.\nBật chạy khi đăng xuất nếu máy chủ cần hoạt động liên tục.",9);explanation.Height=60;explanation.AutoSize=false;explanation.Width=520;body.Controls.Add(explanation);
    var row=new FlowLayoutPanel{Width=520,Height=45,WrapContents=false};body.Controls.Add(row);var install=Button("Cài Tailscale");var login=Button("Đăng nhập",true);var copy=Button("Sao chép IP");row.Controls.Add(install);row.Controls.Add(login);row.Controls.Add(copy);var unattended=Button("Chạy khi đăng xuất");unattended.Width=190;body.Controls.Add(unattended);
    install.Click+=async(a,b)=>{install.Enabled=false;try{await nas.Admin("Install",new NasProfile());status.Text="Đã cài. Đăng nhập Tailscale để tiếp tục.";}catch(Exception e){status.Text=e.Message;}finally{install.Enabled=true;}};
    login.Click+=async(a,b)=>{login.Enabled=false;try{await nas.Login(t=>status.Text=t);var state=await nas.Status();status.Text=state.Ready?"Đã kết nối · "+state.Address:state.State;}catch(Exception e){status.Text=e.Message;}finally{login.Enabled=true;}};
    copy.Click+=async(a,b)=>{try{var state=await nas.Status();if(!state.Ready)throw new Exception("Tailscale chưa kết nối.");Clipboard.SetText(state.Address);status.Text="Đã sao chép IP: "+state.Address;}catch(Exception e){status.Text=e.Message;}};
    unattended.Click+=async(a,b)=>{unattended.Enabled=false;try{await nas.Admin("Unattended",new NasProfile());status.Text="Tailscale sẽ tiếp tục chạy sau khi đăng xuất Windows.";}catch(Exception e){status.Text=e.Message;}finally{unattended.Enabled=true;}};
    dialog.ShowDialog(this);
   }
  }
  private void SettingsDialog(){using(var dialog=new Form{Text="Cài đặt · "+Text,Size=new Size(510,330),StartPosition=FormStartPosition.CenterParent,Font=Font}){var body=new FlowLayoutPanel{Dock=DockStyle.Fill,FlowDirection=FlowDirection.TopDown,Padding=new Padding(24)};dialog.Controls.Add(body);var startup=new CheckBox{Text="Khởi chạy tool này cùng Windows",AutoSize=true,Checked=SuiteStartup.Enabled(server)};startup.CheckedChanged+=(a,b)=>SuiteStartup.Set(server,startup.Checked);body.Controls.Add(startup);var automatic=new CheckBox{Text="Tự kiểm tra bản cập nhật mỗi 6 giờ",AutoSize=true,Checked=SuiteUpdate.Automatic(home)};automatic.CheckedChanged+=(a,b)=>SuiteUpdate.SetAutomatic(home,automatic.Checked);body.Controls.Add(automatic);var update=Button("Kiểm tra cập nhật");update.Click+=async(a,b)=>{update.Enabled=false;try{await SuiteUpdate.DownloadAndLaunch(this,server?null:engine);}catch(Exception e){MessageBox.Show(e.Message);}finally{update.Enabled=true;}};body.Controls.Add(update);var exit=Button("Thoát an toàn");exit.Click+=async(a,b)=>{dialog.Close();await Work(ExitSafely);};body.Controls.Add(exit);dialog.ShowDialog(this);}}
  private void ShowActivity(){var text=string.Join("\n\n",engine.Store.Load().Select(p=>p.Name+" · "+engine.Runtime(p).State+"\n"+engine.Runtime(p).Message));MessageBox.Show(this,text==""?"Chưa có kết nối.":text,"Hoạt động");}
  private async Task ExitSafely(){timer.Stop();try{if(engine!=null)await engine.StopAll();exiting=true;Close();}catch{timer.Start();throw;}}
  public void ShowWindow(){Show();WindowState=FormWindowState.Normal;Activate();}
